EXECUTE IMMEDIATE $$
DECLARE
    col_count INT;
BEGIN
    SELECT COUNT(*) INTO :col_count
    FROM INFORMATION_SCHEMA.COLUMNS
    WHERE TABLE_SCHEMA = 'APP' AND TABLE_NAME = 'CFG' AND COLUMN_NAME = 'NOTE';
    IF (col_count = 0) THEN
        ALTER TABLE app.cfg ADD COLUMN note VARCHAR;
    END IF;
END;
$$
